-- One-time: the SOLIDMILL brand (Solutions, Milling) with its uses from
-- the ISCAR intranet e-catalog (Milling), each family linked to its page;
-- families with the same description share a use. An existing SOLIDMILL is kept:
-- it gets the application, a description if it has none, and the uses it
-- doesn't have (by name).
INSERT INTO "Innovation" ("id", "name", "category", "description")
SELECT 'innovation_solidmill', 'SOLIDMILL', 'Milling', $u$Solid carbide endmills: the Premium line (square, ball nose, toroidal, chamfering, hard materials, aluminum and composite endmills), the economical TEC line and solid ceramic endmills.$u$
WHERE NOT EXISTS (SELECT 1 FROM "Innovation" WHERE upper(regexp_replace("name", '[^A-Za-z0-9]', '', 'g')) = 'SOLIDMILL')
ON CONFLICT DO NOTHING;

UPDATE "Innovation" SET "description" = $u$Solid carbide endmills: the Premium line (square, ball nose, toroidal, chamfering, hard materials, aluminum and composite endmills), the economical TEC line and solid ceramic endmills.$u$
WHERE upper(regexp_replace("name", '[^A-Za-z0-9]', '', 'g')) = 'SOLIDMILL' AND ("description" IS NULL OR trim("description") = '');

INSERT INTO "_ApplicationToInnovation" ("A", "B")
SELECT a."id", i."id"
FROM "Application" a, "Innovation" i
WHERE lower(trim(a."name")) = 'milling' AND upper(regexp_replace(i."name", '[^A-Za-z0-9]', '', 'g')) = 'SOLIDMILL'
ON CONFLICT DO NOTHING;

